import {CAPABILITIES,TEAM_IDS} from './definitions.js';
import {LAYERS,CONNECTORS,coordinationFor,traceMaps} from './relationships.js';
import {escapeHtml as e} from '../shared/utils.js';
const n=x=>x.toLocaleString('en-GB',{maximumFractionDigits:1});
export function relationshipMarkup(session,scenario,job){
 const r=session.relationships,active=r.view,out=coordinationFor(session.layout,scenario,r),layer=LAYERS[active],groups=active==='team'?session.names:layer.groups;
 const baseline=session.baseline?coordinationFor(session.baseline.layout,scenario,{...(session.baseline.relationships||r),effort:r.effort,hours:r.hours}):null;
 const options=(list,value)=>Object.entries(list).map(([key,label])=>`<option value="${key}" ${key===value?'selected':''}>${e(label)}</option>`).join('');
 return `<div class="section-heading"><h2>One organisation, four maps</h2><label for="relationship-view">View <select id="relationship-view">${options(Object.fromEntries(Object.entries(LAYERS).map(([k,v])=>[k,v.label])),active)}</select></label></div><p>The same six capabilities sit in different groups. Move a capability in this view, then follow the selected work through all four maps.</p><div class="relationship-map" id="relationship-map">${TEAM_IDS.map(group=>`<section data-drop-id="${group}"><h3>${e(groups[group])}</h3>${CAPABILITIES.filter(c=>out.maps[active][c.id]===group).map(c=>`<div class="relationship-capability" data-drag-id="${c.id}"><button type="button" class="button quiet" data-drag-handle aria-label="Drag ${c.name} in ${layer.label}">↔ ${c.name}</button><label for="relationship-${c.id}">Move to</label><select id="relationship-${c.id}" data-relationship-cap="${c.id}">${options(groups,group)}</select></div>`).join('')||'<p class="muted">No capabilities</p>'}</section>`).join('')}</div><details class="relationship-trace-details"><summary>Follow ${e(job.label)} across all four maps</summary><div class="relationship-traces">${traceMaps(job,session.layout,r).map(row=>`<div><strong>${row.label}</strong><ol>${row.steps.map(step=>`<li class="${step.crossing?'crossing':''}"><span>${CAPABILITIES.find(c=>c.id===step.capability).name}</span><small>${e(row.id==='team'?session.names[step.group]:LAYERS[row.id].groups[step.group])}${step.crossing?' · crosses a boundary':''}</small></li>`).join('')}</ol></div>`).join('')}</div></details><h2>Who is holding this together?</h2><p>Assign each kind of coordination to a liaison. Each liaison has one shared time budget for the whole 30-day workload. Removing an owner leaves that work uncovered.</p><div class="relationship-budgets">${Object.entries(CONNECTORS).map(([id,label])=>`<label for="connector-${id}">${label}<input id="connector-${id}" data-connector="${id}" type="number" min="0" max="120" step="1" value="${r.hours[id]}"> available hours</label>`).join('')}</div><p class="table-pan-note">Scroll the coordination ledger sideways on a small screen to see hours and uncovered work.</p><div class="relationship-table" tabindex="0" role="region" aria-label="Coordination coverage; scroll sideways on a small screen"><table><thead><tr><th scope="col">Work</th><th scope="col">Owner</th><th scope="col">Hours per crossing</th><th scope="col">Crossings</th><th scope="col">Needed</th><th scope="col">Uncovered</th></tr></thead><tbody>${out.rows.map(row=>`<tr><th scope="row">${row.label}</th><td><label class="sr-only" for="owner-${row.id}">${row.label} owner</label><select id="owner-${row.id}" data-coordination-owner="${row.id}">${options({none:'No owner',...CONNECTORS},row.owner)}</select></td><td><label class="sr-only" for="effort-${row.id}">${row.label} hours per crossing</label><input id="effort-${row.id}" data-coordination-effort="${row.id}" type="number" min="0" max="4" step="0.25" value="r" aria-label="${row.label} hours per crossing"></td><td>${row.crossings}</td><td>${n(row.requested)} h</td><td>${n(row.gap)} h</td></tr>`.replace('value="r"',`value="${r.effort[row.id]}"`)).join('')}</tbody></table></div><p class="relationship-result" id="coordination-result"><strong>${n(out.gap)} hours uncovered</strong> of ${n(out.requested)} hours requested.${baseline?` Pinned maps and owners: ${n(baseline.gap)} hours uncovered, replayed with the current workload, hours per crossing and liaison budgets.`:''}</p><div class="relationship-people">${out.people.map(p=>`<p><strong>${p.label}</strong><br>${n(p.covered)} h covered / ${n(p.requested)} h requested · ${n(p.available)} h available</p>`).join('')}</div><details><summary>What the coordination model assumes</summary><p>Every adjacent stage crossing a map boundary creates one coordination task for that layer. Change its hours per crossing, including zero if that boundary needs no work. The ledger includes all planned work, including jobs unfinished at day 30. Each liaison’s time is shared proportionally across their assigned tasks. Several kinds of work at one handoff are distinct requests, so you should remove any duplicated effort.</p><p>The liaisons have separate, declared coordination budgets. This coverage ledger does not add staff or change the delivery replay above: an uncovered hour has no assumed delay or quality penalty. It exposes a question to investigate. Team membership changes still affect the original FIFO engine.</p><p>Inspired by John Cutler’s <a href="https://cutlefish.substack.com/p/tbm-423-why-defining-teams-is-so" target="_blank" rel="noopener noreferrer">Why Defining Teams Is So Hard</a> and <a href="https://cutlefish.substack.com/p/tbm-422-exception-presence-delegation" target="_blank" rel="noopener noreferrer">Exception, Presence, Delegation</a>. Groupings, liaison names and hours are fictional.</p></details>`;
}
export function relationshipMarkdown(session,scenario){const r=coordinationFor(session.layout,scenario,session.relationships);return['','## Organisational maps and coordination','','Separate coverage ledger for all planned work; no inferred throughput penalty. Liaison budgets are shared proportionally.','',...r.rows.map(x=>`- ${x.label}: ${x.crossings} crossings, ${n(x.requested)} h needed, ${n(x.gap)} h uncovered; owner ${CONNECTORS[x.owner]||'none'}.`),'','```json',JSON.stringify(session.relationships,null,2),'```'];}
